<script lang="ts">
 import {Search,BookOpen,ArrowUpRight} from '@lucide/svelte';import {translator} from './i18n';
 export let language:'ru'|'ro';export let onopen:(action:string)=>void;
 let selected='start',query='';$:t=translator(language);
 type Chapter={id:string;ru:string;ro:string;stepsRu:string[];stepsRo:string[];action?:string};
 const chapters:Chapter[]=[
 {id:'workspace',ru:'Рабочий стол и панель задач',ro:'Desktop și bara de activități',stepsRu:['ПКМ по доступной команде меню позволяет создать ярлык в OpenHaU или на рабочем столе Windows. Команду также можно перетащить на рабочий стол OpenHaU. Пользовательские ярлыки открываются двойным щелчком и перемещаются; фиксированные ярлыки остаются справа.','В контекстном меню рабочего стола включается или отключается привязка к сетке. Удаление ярлыка не удаляет документы или базу.','Нажмите кнопку открытого окна на панели задач, чтобы свернуть или восстановить его. Сгруппированные окна выбираются через предпросмотр. ПКМ по панели позволяет менять подписи, поиск и закрепление. Незакреплённая панель переносится за ручку к краю окна.','Часы открывают календарь. Кнопка уведомлений показывает историю текущего сеанса; сообщения можно удалить по одному или очистить все.','В параметрах доступны поиск отдельных настроек и назначение сочетаний клавиш. Выберите поле команды и нажмите сочетание; Backspace удаляет назначение.'],stepsRo:['Clicul dreapta pe o comandă disponibilă permite crearea unei scurtături în OpenHaU sau pe desktopul Windows. Comanda poate fi și trasă pe desktopul OpenHaU. Scurtăturile personale se deschid prin dublu clic și pot fi mutate; cele fixe rămân în dreapta.','Meniul desktopului permite activarea alinierii la grilă. Eliminarea unei scurtături nu șterge documente sau baza.','Apăsați butonul unei ferestre din bară pentru minimizare sau restaurare. Ferestrele grupate se aleg din previzualizare. Clicul dreapta pe bară permite configurarea titlurilor, căutării și blocării. Bara deblocată se mută de mâner la marginea ferestrei.','Ceasul deschide calendarul. Butonul notificărilor arată istoricul sesiunii; mesajele se pot elimina separat sau împreună.','Setările permit căutarea parametrilor individuali și atribuirea comenzilor rapide. Selectați câmpul și apăsați combinația; Backspace o elimină.']},

 {id:'start',ru:'Начало работы',ro:'Primii pași',stepsRu:['На приветственном экране выберите базу или нажмите «Создать базу». Название вводится в отдельном окне.','«Добавить существующую» открывает выбранный файл базы. «Сохранить» записывает изменения в этот же файл. Для переноса на другой компьютер скопируйте его после сохранения.','После открытия базы справочники, документы и отчёты доступны через верхнее меню. Каждое рабочее окно можно переместить, свернуть, развернуть и выбрать на нижней панели.'],stepsRo:['În ecranul de pornire selectați o bază sau apăsați „Creează o bază”. Denumirea se introduce într-o fereastră separată.','„Adaugă o bază existentă” deschide fișierul selectat. „Salvare” scrie modificările în același fișier. Copiați fișierul salvat pentru a-l transfera pe alt calculator.','După deschiderea bazei, cataloagele, documentele și rapoartele sunt disponibile în meniul superior. Ferestrele pot fi mutate, minimizate, maximizate și selectate din bara de jos.']},
 {id:'databases',ru:'Базы и сохранение',ro:'Baze și salvare',action:'file:home',stepsRu:['Используйте «Сохранить» или Ctrl+S после применения изменений в документах. Сначала завершите ввод и примените показания: сохранение базы не заменяет применение открытой формы.','Через меню «Файл» откройте каталог баз для переключения. Перед выходом или сменой базы выберите сохранение, продолжение без сохранения или отмену. Отказ от сохранения удаляет только несохранённый ввод; ранее записанные изменения остаются в файле.','Автоматическое открытие базы настраивается в каталоге баз и в общих настройках. Выберите «Показывать выбор базы», чтобы отключить автовход.','«Сохранить базу как…» создаёт новый переносимый файл из текущей базы. «Импортировать копию JSON…» создаёт отдельную копию. При редактировании JSON вручную сначала закройте базу в программе и сохраняйте идентификаторы и связи.'],stepsRo:['Folosiți „Salvare” sau Ctrl+S după aplicarea modificărilor din documente. Finalizați și aplicați mai întâi indexurile: salvarea bazei nu înlocuiește aplicarea formularului.','Deschideți catalogul bazelor din meniul „Fișier”. La ieșire sau schimbarea bazei alegeți salvarea, continuarea fără salvare sau anularea. Renunțarea elimină doar datele nesalvate; modificările deja scrise rămân în fișier.','Deschiderea automată se configurează în catalogul bazelor și în setările generale. Alegeți afișarea catalogului pentru a o dezactiva.','„Salvează baza ca…” creează un fișier portabil nou. „Importă o copie JSON…” creează o copie separată. Închideți baza înainte de editarea manuală a fișierului JSON și păstrați identificatorii și legăturile.']},
 {id:'accounts',ru:'Лицевые счета',ro:'Conturi personale',action:'accounts',stepsRu:['В списке задайте дату и отбор. Двойной щелчок по строке открывает карточку с шестью вкладками: основное, проживающие, услуги, приборы, дополнительные объекты и характеристики.','Открытие и закрытие счёта, изменение информации и услуг оформляются отдельными документами через меню «Лицевые счета». «Сохранить» оставляет черновик, OK проводит документ. Движения и история открываются в отдельных окнах.','В карточке выберите дату для просмотра истории. Изменение статуса проживающего или услуги открывает соответствующий документ. Подключение общего прибора к одному счёту не отключает его у остальных.','В документе изменения информации на вкладке параметров расчёта задайте людей для платы за мусор в месяце документа. Это количество хранится отдельно от зарегистрированных и фактически проживающих.','Начальные остатки вводятся по услугам до появления движений. Аванс относится на явно выбранную услугу; начальные показания доступны собственным приборам без истории.','Изменение услуг сохраняет точную дату в истории, но месячный расчёт использует итоговый состав услуг месяца без посуточного распределения. Импортированные исторические документы доступны только для просмотра.'],stepsRo:['Selectați data și filtrele în listă. Dublul clic deschide fișa cu șase file: principal, locatari, servicii, contoare, obiecte suplimentare și caracteristici.','Deschiderea și închiderea contului, modificările informațiilor și serviciilor se înregistrează prin documente separate din meniul conturilor. „Salvează” păstrează o ciornă; OK aplică documentul. Mișcările și istoricul se deschid separat.','Selectați data în fișă pentru istoric. Schimbarea stării unui locatar sau serviciu deschide documentul corespunzător. Schimbarea legăturii unui cont cu un contor comun nu deconectează celelalte conturi.','În parametrii de calcul ai documentului de modificare indicați persoanele taxate pentru deșeuri în luna documentului. Valoarea este separată de persoanele înregistrate și cele care locuiesc.','Introduceți soldurile inițiale pe servicii înainte de apariția mișcărilor. Avansul necesită un serviciu selectat explicit; indexurile inițiale sunt permise contoarelor proprii fără istoric.','Modificările serviciilor păstrează data exactă în istoric; calculul lunar utilizează componența finală a serviciilor lunii, fără repartizare zilnică. Documentele istorice importate sunt doar pentru vizualizare.']},
 {id:'services',ru:'Услуги и тарифы',ro:'Servicii și tarife',action:'services',stepsRu:['В карточке услуги задаются единица измерения, основание расчёта, поставщик и порядок отображения. История тарифов хранится отдельно от наименования услуги.','Для нового тарифа укажите дату вступления в силу. Изменение текущего значения не должно переписывать старые тарифы и сохранённые начисления.','Если тариф изменился внутри месяца, бухгалтер может ввести среднюю цену за переходный месяц вручную, а следующий тариф — с первого числа следующего месяца.','Документ изменения тарифов позволяет подготовить несколько строк и применить их вместе. Проверьте даты и услуги перед применением.'],stepsRo:['În fișa serviciului se stabilesc unitatea, baza de calcul, furnizorul și ordinea afișării. Istoricul tarifelor se păstrează separat de denumire.','Indicați data de intrare în vigoare a tarifului nou. Nu rescrieți tarifele vechi sau calculele păstrate.','Dacă tariful se schimbă în cursul lunii, contabilul poate introduce manual prețul mediu pentru luna de tranziție, apoi tariful următor de la prima zi a lunii următoare.','Documentul de modificare a tarifelor permite pregătirea și aplicarea mai multor rânduri împreună. Verificați datele și serviciile înainte de aplicare.']},
 {id:'meters',ru:'Приборы и показания',ro:'Contoare și indexuri',action:'individual-meters',stepsRu:['У физического прибора укажите лицевой счёт, услугу, серийный номер, единицу и срок подключения. Общий прибор не заменяет индивидуальное потребление.','Введите дату и показание. Расход получается из последовательных показаний одного прибора; несколько приборов одного счёта учитываются отдельными строками.','Если показание уменьшилось, проверьте замену прибора или ошибку ввода. Отсутствующее показание не считается нулевым расходом.','Перед закрытием месяца проверьте предупреждения. Предыдущие и последние показания с датами выводятся в квитанции при наличии этих данных.'],stepsRo:['Pentru contorul fizic indicați contul, serviciul, seria, unitatea și perioada conectării. Contorul comun nu înlocuiește consumul individual.','Introduceți data și indexul. Consumul rezultă din indexurile succesive ale aceluiași contor; mai multe contoare se afișează separat.','Dacă indexul a scăzut, verificați înlocuirea contorului sau eroarea de introducere. Lipsa indexului nu reprezintă consum zero.','Verificați avertizările înainte de închiderea lunii. Indexurile precedente și curente, cu date, apar în factură dacă sunt disponibile.']},
 {id:'shared',ru:'Общие счётчики',ro:'Contoare comune',action:'readings',stepsRu:['Соедините общий прибор с индивидуальными приборами и выберите услугу для распределяемой разницы.','Разница равна расходу общего прибора минус индивидуальные расходы. Она делится поровну между лицевыми счетами, участвующими в распределении за месяц.','Исключения задаются помесячно. Расход освобождённого потребителя продолжает вычитаться из общего, но доля разницы ему не начисляется.','Проверьте отрицательную разницу, отсутствующие показания и тариф услуги разницы. Непроверенные значения не следует распределять автоматически.'],stepsRo:['Conectați contorul comun la contoarele individuale și selectați serviciul pentru diferența repartizată.','Diferența este consumul comun minus consumurile individuale. Se împarte egal între conturile participante în luna respectivă.','Excluderile sunt lunare. Consumul unui cont exclus se scade în continuare din consumul comun, dar contul nu primește o cotă din diferență.','Verificați diferențele negative, indexurile lipsă și tariful diferenței. Nu repartizați automat valorile neverificate.']},
 {id:'waste',ru:'Мусор и проживающие',ro:'Deșeuri și locatari',action:'readings',stepsRu:['Для платы за человека используйте количество людей в лицевом счёте за текущий месяц.','Накопительный способ также поддерживается: если было 3, а введено 7, расход за месяц равен 4 человекам. Не смешивайте прямое число людей и накопительное показание в одном месяце.','При учёте по нескольким квартирам проверьте полноту заполнения. Общий месячный показатель счёта заменяет детализацию только выбранного месяца.'],stepsRo:['Pentru taxa per persoană folosiți numărul de persoane al contului în luna curentă.','Este disponibil și modul cumulativ: de la 3 la 7 rezultă 4 persoane pentru lună. Nu combinați numărul direct și indexul cumulativ în aceeași lună.','La evidența pe mai multe apartamente verificați completarea tuturor rândurilor. Totalul lunar al contului înlocuiește detalierea doar pentru luna selectată.']},
 {id:'payments',ru:'Оплаты и распределение',ro:'Plăți și repartizare',action:'payments',stepsRu:['Укажите лицевой счёт, фактическую дату поступления и сумму. Дата ввода хранится отдельно.','Автоматическое распределение направляет оплату пропорционально положительному долгу по услугам с сохранением точной общей суммы.','Ручное изменение суммы обслуживания дома меняет распределение оставшейся суммы, а не общий размер поступления. Переплату не следует повторно добавлять как отдельный платёж.','Платёж группового документа просматривается через этот документ, чтобы его строки и распределение не расходились.'],stepsRo:['Indicați contul, data efectivă a încasării și suma. Data înregistrării se păstrează separat.','Repartizarea automată distribuie plata proporțional cu datoria pozitivă pe servicii, păstrând suma totală exactă.','Modificarea manuală a cotei pentru deservirea blocului schimbă repartizarea restului, nu suma încasată. Nu înregistrați supraplata din nou ca plată separată.','Plata unui document colectiv se consultă din documentul respectiv pentru a păstra concordanța rândurilor și repartizării.']},
 {id:'batches',ru:'Групповой ввод оплаты',ro:'Introducerea plăților în grup',action:'payment-batches',stepsRu:['В журнале нажмите «Добавить» или откройте документ двойным щелчком. Каждый редактор открывается в отдельном окне.','Укажите дату и вариант оплаты. «Заполнить» добавляет действующие счета, «Подбор» открывает выбор лицевых счетов. В параметрах укажите месяц долга и услугу обслуживания дома.','Введите суммы поступлений. Выберите строку и нажмите «Расшифровка платежа»: распределение откроется в отдельном окне. Вручную меняется только сумма обслуживания дома; остальные услуги распределяются по долгу. Нажмите OK в расшифровке, чтобы применить её к строке.','«Сохранить» записывает черновик. OK проводит документ целиком и закрывает редактор. Нулевые строки не создают оплат. «Движения» показывает связанные записи по услугам.','Отмена проведения возвращает родной документ в черновик. Она недоступна для закрытых периодов, связанных банковских документов и последующих оплат. Помеченные черновики удаляются через «Сервис → Удаление помеченных объектов» после проверки ссылок.','Импортированные документы доступны только для просмотра с исходным распределением. Для исправления истории используйте отдельную корректировку.'],stepsRo:['În jurnal apăsați „Adaugă” sau deschideți documentul prin dublu clic. Fiecare editor se deschide într-o fereastră separată.','Indicați data și modalitatea de plată. „Completează” adaugă conturile deschise, iar „Selectare” deschide alegerea conturilor. În parametri indicați luna datoriei și serviciul de deservire a blocului.','Introduceți sumele încasate. Selectați un rând și apăsați „Repartizarea plății” pentru o fereastră separată. Manual se modifică doar suma deservirii; celelalte servicii se repartizează după datorie. Apăsați OK pentru a aplica repartizarea rândului.','„Salvează” păstrează ciorna. OK aplică întregul document și închide editorul. Rândurile nule nu creează plăți. „Înregistrări” afișează repartizările pe servicii.','Anularea aplicării readuce documentul nativ la ciornă. Nu este disponibilă pentru perioade închise, documente bancare legate sau plăți ulterioare. Ciornele marcate se șterg din meniul Serviciu după verificarea referințelor.','Documentele importate se consultă cu repartizarea originală. Pentru corectarea istoricului folosiți o ajustare separată.']},
 {id:'reports',ru:'Ведомости и отчёт по оплате',ro:'Balanțe și raportul de plăți',action:'reports',stepsRu:['Откройте нужный отчёт через меню «Отчёты», задайте период и отбор. Кнопка «…» выбирает значение из справочника.','«Настройка…» открывает отдельное окно: на вкладке «Отбор» задаются условия, на вкладке «Сортировка» — порядок строк.','Ведомость по услугам можно группировать по услугам, их видам или обоим признакам. Разворот по лицевым счетам и адреса включаются отдельно.','Отчёт по оплатам показывает услуги по столбцам и группирует поступления по варианту оплаты либо по дате. Нераспределённая часть отражается отдельно.','Нажмите «Сформировать». После изменения параметров сформируйте отчёт заново. Предварительные начисления в ведомости включаются отдельным флажком.'],stepsRo:['Deschideți raportul din meniul „Rapoarte”, indicați perioada și filtrele. Butonul „…” selectează valoarea din catalog.','„Configurare…” deschide o fereastră separată cu filele „Filtrare” și „Sortare”.','Balanța pe servicii se poate grupa după servicii, tipuri sau ambele. Detalierea pe conturi și adresele se activează separat.','Raportul de plăți afișează serviciile în coloane și grupează încasările după modalitate sau dată. Partea nerepartizată apare separat.','Apăsați „Generează”. După schimbarea parametrilor generați din nou. Calculele provizorii se includ în balanță printr-o opțiune separată.']},
 {id:'receipts',ru:'Квитанции и оформление',ro:'Facturi și aspect',action:'receipts',stepsRu:['Выберите месяц и лицевые счета, затем проверьте квитанцию в предпросмотре. Сверьте начисления, оплаты, остаток и показания.','Срок оплаты задаётся на конкретный месяц. Формат дат и расчётного месяца меняется в общих настройках.','В оформлении выберите макет, цвет, язык и логотип организации. Доступны растровые изображения и SVG. Настройки оформления можно сохранить в пресет.','Внешний вид квитанции не меняет расчёт. Для печати чёрно-белым проверьте различимость текста и линий в предпросмотре.'],stepsRo:['Selectați luna și conturile, apoi verificați factura în previzualizare: calcule, plăți, sold și indexuri.','Termenul de plată se stabilește pentru luna respectivă. Formatul datelor și al lunii se schimbă în setările generale.','Alegeți șablonul, culoarea, limba și sigla organizației. Sunt acceptate imagini raster și SVG. Aspectul poate fi salvat ca presetare.','Aspectul nu modifică sumele calculate. Pentru imprimare alb-negru verificați lizibilitatea textului și liniilor.']},
 {id:'export',ru:'Печать, PDF и Excel',ro:'Imprimare, PDF și Excel',stepsRu:['«Печать» открывает системную печать. «Сохранить PDF» — отдельное действие прямого сохранения файла в Windows.','Excel XLSX сохраняет числовые суммы, текстовые номера счетов, ширину столбцов и оформление шапки. CSV содержит только данные и не хранит ширину или цвет.','HTML остаётся отдельным форматом. Старые автоматические выгрузки XML используют SpreadsheetML и не являются XLSX.','Перед отправкой документа проверьте период, отбор, итоговую сумму и получателя. Экспорт может содержать персональные и финансовые данные.'],stepsRo:['„Imprimare” deschide imprimarea sistemului. „Salvează PDF” creează direct un fișier în Windows, ca acțiune separată.','Excel XLSX păstrează sumele numerice, numerele de cont ca text, lățimile coloanelor și antetul. CSV conține doar date, fără lățimi sau culori.','HTML rămâne format separat. Exporturile automate XML mai vechi folosesc SpreadsheetML, nu XLSX.','Înainte de trimitere verificați perioada, filtrele, totalul și destinatarul. Exportul poate conține date personale și financiare.']},
 {id:'backup',ru:'Резервные копии и история',ro:'Copii de siguranță și istoric',action:'settings',stepsRu:['В настройках выберите папку резервного копирования. Она должна быть доступна для записи. Периодически сохраняйте копию на другом носителе.','Закрытие месяца фиксирует начисления в истории. Не заменяйте сохранённые периоды пересчётом по сегодняшнему тарифу.','Перед импортом или исправлением истории сделайте отдельную копию. Новая версия читает старые форматы; старая версия может не понимать новые данные.','При ошибке сохранения не закрывайте программу до проверки сообщения и выбранного пути. Наличие копии следует проверять, а не предполагать.'],stepsRo:['Selectați în setări un dosar pentru copii de siguranță, disponibil pentru scriere. Păstrați periodic o copie pe alt suport.','Închiderea lunii fixează calculele în istoric. Nu înlocuiți perioadele păstrate prin recalculare la tariful actual.','Faceți o copie separată înainte de import sau corectarea istoricului. Versiunile noi citesc formatele vechi; cele vechi pot să nu înțeleagă datele noi.','La o eroare de salvare verificați mesajul și calea înainte de a închide aplicația. Verificați existența copiei.']}
 ];
 $:visible=chapters.filter(c=>[c[language],...(language==='ru'?c.stepsRu:c.stepsRo)].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 $:current=query?null:chapters.find(c=>c.id===selected);
</script>
<div class="manual"><aside><a class="button secondary" href="https://oldschoolnetwork.online/openhau/wiki/index.html" target="_blank" rel="noreferrer"><ArrowUpRight size={16}/>{t("Онлайн документация","Documentație online")}</a><label class="manual-search"><Search size={16}/><input aria-label={t('Поиск в документации','Căutare în documentație')} placeholder={t('Поиск','Căutare')} bind:value={query}/></label><nav aria-label={t('Разделы руководства','Secțiunile ghidului')}>{#each visible as chapter}<button class:chosen={selected===chapter.id&&!query} onclick={()=>{selected=chapter.id;query='';}}><BookOpen size={16}/>{chapter[language]}</button>{/each}</nav></aside><section>{#each current?[current]:visible as chapter}<article><h2>{chapter[language]}</h2><ol>{#each language==='ru'?chapter.stepsRu:chapter.stepsRo as step}<li>{step}</li>{/each}</ol>{#if chapter.action}<button class="button secondary" onclick={()=>onopen(chapter.action!)}><ArrowUpRight size={16}/>{t('Открыть раздел','Deschide secțiunea')}</button>{/if}</article>{/each}{#if !visible.length}<p>{t('Ничего не найдено. Измените запрос.','Niciun rezultat. Modificați căutarea.')}</p>{/if}</section></div>
<style>.manual{display:grid;grid-template-columns:240px minmax(0,1fr);min-height:100%;gap:20px}.manual aside{padding:12px;border-right:1px solid var(--border)}.manual-search{display:flex;align-items:center;gap:8px}.manual-search input{width:100%;min-width:0}.manual nav{display:grid;gap:4px;margin-top:14px}.manual nav button{display:flex;gap:9px;align-items:center;padding:10px 8px;text-align:left;border:0;background:transparent;color:var(--text)}.manual nav button.chosen{background:var(--hover);box-shadow:inset 3px 0 var(--accent)}.manual section{padding:12px 20px 24px 0;min-width:0}.manual h2{font-size:22px;font-weight:500;margin:6px 0 20px}.manual li{line-height:1.65;margin-bottom:14px}.manual article{margin-bottom:34px}@media(max-width:650px){.manual{grid-template-columns:180px minmax(0,1fr);gap:12px}}</style>

